const headers = $input.first().json.headers || {};

// Handle both cases safely
const authHeader =
  headers.authorization ||
  headers.Authorization ||
  headers['Authorization'];

if (!authHeader || authHeader !== "Bearer your_n8n_bearer_secret_here") {
  throw new Error("Unauthorized request ❌");
}

return $input.all();

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}

return $input.all();

const data = $input.item.json;
const userId = data.userId;

if (!userId) {
  throw new Error("User ID missing for rate limit");
}

// Initialize global storage
if (!globalThis.userRequests) {
  globalThis.userRequests = {};
}

// Create array for user
if (!globalThis.userRequests[userId]) {
  globalThis.userRequests[userId] = [];
}

const now = Date.now();

// Keep only last 10 minutes
globalThis.userRequests[userId] = globalThis.userRequests[userId].filter(
  t => now - t < 10 * 60 * 1000
);

// LIMIT: max 3 requests
if (globalThis.userRequests[userId].length >= 3) {
  throw new Error("Too many submissions. Try again later.");
}

// Add current request
globalThis.userRequests[userId].push(now);

return $input.all();

const data = $input.item.json;

// Team Name
if (!data.teamName || data.teamName.length < 3) {
  throw new Error("Invalid Team Name");
}

// Email (FIXED)
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!data.email || !emailRegex.test(data.email)) {
  throw new Error("Invalid Email");
}

// PDF link
if (!data.pdfLink || !data.pdfLink.includes("drive.google.com")) {
  throw new Error("Invalid PDF Link");
}

// User ID
if (!data.userId) {
  throw new Error("User ID missing");
}

return $input.all();

